\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath,amssymb}

% shorthand for the summary statistics used throughout
\newcommand{\mean}[1]{\bar{#1}}
\newcommand{\sd}[1]{\sigma_{#1}}
\newcommand{\gcd}{\operatorname{g.c.d.}}
\newcommand{\ci}[1]{\mathrm{CI}_{#1}}
\renewcommand{\ci}[1]{[#1 \pm #2]}

\title{Minimum Wages and Hours Worked:\\A Synthetic Control Reassessment}
\author{R.~Duarte and K.~Owusu}
\date{August 2026}

\begin{document}
\maketitle

\section{Results}
The pooled estimate $\mean{x}$ across the 41 treatment windows
is small in levels,
and its dispersion $\sd{x}$ is dominated by the
2009--2011 recoveries.
Our headline interval is reported as $\ci{0.31}{0.04}$,
which excludes the benchmark estimate.

For the exposure weights we use the greatest common divisor
of the batch sizes, $\gcd(m, n) = 12$,
so that the synthetic control weights are expressed
in twelfths.

\section{Discussion}
The reassessment narrows the range of plausible effects
relative to the original study,
mostly by excluding windows with contaminated controls.

\end{document}

